/** Read a My-Projects multi-select filter from a URL param or the saved
 *  localStorage blob. Accepts the comma-separated list written today and the
 *  pre-multiselect single value (whose `_all` sentinel means "no filter"), so
 *  existing bookmarks and stored state survive the upgrade. */
function parseProjectFilterList(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.filter((v): v is string => typeof v === 'string' && v !== '' && v !== '_all');
  if (typeof raw !== 'string' || !raw || raw === '_all') return [];
  return raw.split(',').map((v) => v.trim()).filter((v) => v && v !== '_all');
}
