function readTabFromUrl(): string | null {
  try {
    const tab = new URLSearchParams(window.location.search).get('tab');
    if (!tab) return null;
    if (tab === 'relayops-admin') return 'relayops-admin-handover';
    if (tab === 'audit-logs') return 'relayops-admin-issues';
    return KNOWN_TABS.includes(tab as (typeof KNOWN_TABS)[number]) ? tab : null;
  } catch {
    return null;
  }
}

function readWorkbenchIssueIdFromUrl(): number | null {
  try {
    const raw = new URLSearchParams(window.location.search).get('workbenchIssueId');
    const parsed = raw ? Number(raw) : NaN;
    return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
  } catch {
    return null;
  }
}

function readPositiveIntParam(name: string): number | null {
  try {
    const raw = new URLSearchParams(window.location.search).get(name);
    const parsed = raw ? Number(raw) : NaN;
    return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
  } catch {
    return null;
  }
}

function readProjectsContextFromUrl(): { projectId: number | null; productId: number | null; projectView: 'projects' | 'products' | 'assets' } {
  const projectId = readPositiveIntParam('projectId');
  const productId = readPositiveIntParam('productId');
  try {
    const raw = new URLSearchParams(window.location.search).get('projectView');
    const projectView = raw === 'projects' || raw === 'products' || raw === 'assets' ? raw : 'projects';
    return { projectId, productId, projectView };
  } catch {
    return { projectId, productId, projectView: 'projects' };
  }
}

function writeUrlState(
  tab: string,
  replace = false,
  workbenchIssueId: number | null = null,
  projectsContext?: { projectId?: number | null; productId?: number | null; projectView?: 'projects' | 'products' | 'assets' | null },
) {
  try {
    const params = new URLSearchParams(window.location.search);
    if (tab === DEFAULT_TAB) params.delete('tab');
    else params.set('tab', tab);
    if ((tab === 'actions' || tab === 'workbench') && workbenchIssueId !== null) params.set('workbenchIssueId', String(workbenchIssueId));
    else params.delete('workbenchIssueId');
    if (tab === 'projects') {
      const projectId = projectsContext?.projectId ?? null;
      const productId = projectsContext?.productId ?? null;
      const projectView = projectsContext?.projectView ?? null;
      if (projectId !== null) params.set('projectId', String(projectId));
      else params.delete('projectId');
      if (productId !== null) params.set('productId', String(productId));
      else params.delete('productId');
      if (projectView) params.set('projectView', projectView);
      else params.delete('projectView');
    } else {
      params.delete('projectId');
      params.delete('productId');
      params.delete('projectView');
    }
    const query = params.toString();
    const nextUrl = `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`;
    window.history[replace ? 'replaceState' : 'pushState'](null, '', nextUrl);
  } catch {
    // Ignore browser history failures.
  }
}

// ── SLA Clock ────────────────────────────────────────────────────────

/** Parse a UTC datetime string from the backend, ensuring it's treated as UTC. */
function parseUTCDate(dateStr: string): number {
  // Backend returns UTC datetimes without 'Z' suffix; append it so JS parses as UTC
  const s = dateStr.endsWith('Z') || dateStr.includes('+') ? dateStr : dateStr + 'Z';
  return new Date(s).getTime();
}

// ── Timezone display (Asia/Singapore) ────────────────────────────────
// Backend persists all timestamps as naive UTC (datetime.utcnow()). The browser's
// `new Date("...")` would treat those as local time, so every displayed timestamp
// must be (a) parsed as UTC, then (b) rendered in Singapore time. These helpers do
// both and are independent of the viewer's own browser timezone.

const APP_TIME_ZONE = 'Asia/Singapore';

/** Parse a backend datetime (UTC, usually without 'Z') / number / Date into a real instant. */
function parseBackendDate(input: string | number | Date): Date {
  if (input instanceof Date) return input;
  if (typeof input === 'number') return new Date(input);
  const s = input.endsWith('Z') || /[+-]\d\d:?\d\d$/.test(input) ? input : input + 'Z';
  return new Date(s);
}

/**
 * Shift an instant to its Asia/Singapore wall-clock time, returned as a Date whose
 * LOCAL fields equal the Singapore fields. Feeding this into date-fns `format`
 * therefore renders Singapore time regardless of the viewer's browser timezone.
 */
function toSGTWallClock(instant: Date): Date {
  if (Number.isNaN(instant.getTime())) return instant;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: APP_TIME_ZONE,
    hour12: false,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
    .formatToParts(instant)
    .reduce<Record<string, string>>((acc, p) => {
      acc[p.type] = p.value;
      return acc;
    }, {});
  const hour = parts.hour === '24' ? '0' : parts.hour; // some engines emit '24' for midnight
  return new Date(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(hour),
    Number(parts.minute),
    Number(parts.second),
  );
}

/** Format a backend UTC datetime in Singapore time using date-fns format tokens. */
function formatSGT(input: string | number | Date, pattern: string): string {
  const instant = parseBackendDate(input);
  if (Number.isNaN(instant.getTime())) return '—';
  return format(toSGTWallClock(instant), pattern);
}

// ── Datetime INPUT boundary (the inverse of the display helpers) ──────
// `<input type="datetime-local">` has no timezone: its value is a bare
// wall-clock string. The display layer renders everything in Singapore time,
// so inputs must be interpreted as Singapore wall-clock too — NOT the viewer's
// browser timezone. Doing the conversion here (instead of `new Date(value)`,
// which assumes browser-local) is what keeps "09:00" meaning 09:00 SGT on a
// laptop, a UTC VDI, or a server-time box alike. Singapore is a fixed UTC+8
// with no DST, so the offset is constant.
const SGT_UTC_OFFSET = '+08:00';

/** A datetime-local value (Singapore wall-clock) → UTC ISO string for the backend. */
function sgtInputToUTCISO(localValue: string): string {
  // datetime-local is "yyyy-MM-ddTHH:mm" (seconds optional); pin it to SGT.
  const withSeconds = /T\d\d:\d\d$/.test(localValue) ? `${localValue}:00` : localValue;
  return new Date(`${withSeconds}${SGT_UTC_OFFSET}`).toISOString();
}

/** A backend UTC instant → datetime-local value in Singapore wall-clock. */
function utcToSGTInput(input: string | number | Date): string {
  const instant = parseBackendDate(input);
  if (Number.isNaN(instant.getTime())) return '';
  return format(toSGTWallClock(instant), "yyyy-MM-dd'T'HH:mm");
}

// ── Header masking for persisted API checks ──────────────────────────
// MVP stores headers as plain JSON in the DB; the UI masks credential
// values in list / read-only views so they don't leak by shoulder-surf or
// screenshot. Edit mode reveals the original — the user explicitly chose
// to see it. Names are matched case-insensitively.
const SENSITIVE_HEADER_NAMES = new Set([
  'authorization', 'proxy-authorization', 'cookie', 'set-cookie',
  'x-api-key', 'x-auth-token', 'x-access-token', 'api-key',
]);
function isSensitiveHeader(name: string): boolean {
  return SENSITIVE_HEADER_NAMES.has((name || '').trim().toLowerCase());
}
function maskHeaderValue(name: string, value: string): string {
  if (!isSensitiveHeader(name)) return value;
  if (!value) return '';
  // Preserve scheme prefix ("Bearer ", "Basic ") so the user still sees
  // what auth scheme this is, without leaking the token itself.
  const m = /^(\s*(?:Bearer|Basic|Digest|Negotiate|Token)\s+)/i.exec(value);
  if (m) return `${m[1]}***`;
  return '***';
}

function parseTargetPage(raw: string, totalPages: number): number | null {
  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) return null;
  return Math.max(1, Math.min(totalPages, Math.floor(parsed)));
}

const SLAClock = ({ deadline }: { deadline: number }) => {
  const [timeLeft, setTimeLeft] = useState(differenceInSeconds(deadline, Date.now()));

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(differenceInSeconds(deadline, Date.now()));
    }, 1000);
    return () => clearInterval(timer);
  }, [deadline]);

  const isOverdue = timeLeft <= 0;
  const absTime = Math.abs(timeLeft);
  const hours = Math.floor(absTime / 3600);
  const minutes = Math.floor((absTime % 3600) / 60);
  const seconds = absTime % 60;

  return (
    <div className={`flex items-center gap-1.5 font-mono text-sm ${isOverdue ? 'text-relayops-brand' : 'text-green-600'}`}>
      <Clock className="w-4 h-4" />
      <span>
        {isOverdue ? '-' : ''}
        {String(hours).padStart(2, '0')}:{String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}
      </span>
      {isOverdue && <span className="text-[10px] font-bold uppercase ml-1">Overdue</span>}
    </div>
  );
};

function PaginationControls({
  currentPage,
  totalPages,
  pageInput,
  setPageInput,
  onPrev,
  onNext,
  onGo,
}: {
  currentPage: number;
  totalPages: number;
  pageInput: string;
  setPageInput: (v: string) => void;
  onPrev: () => void;
  onNext: () => void;
  onGo: () => void;
}) {
  return (
    <div className="flex items-center justify-between text-sm">
      <span className="text-slate-500">Page {currentPage} / {totalPages}</span>
      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" disabled={currentPage <= 1} onClick={onPrev}>
          Prev
        </Button>
        <Input
          type="number"
          min={1}
          max={totalPages}
          className="h-8 w-20"
          value={pageInput}
          onChange={e => setPageInput(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter') onGo(); }}
        />
        <Button variant="outline" size="sm" onClick={onGo}>
          Go
        </Button>
        <Button variant="outline" size="sm" disabled={currentPage >= totalPages} onClick={onNext}>
          Next
        </Button>
      </div>
    </div>
  );
}

