function issueTypeLabel(type: string) {
  // Managers think in "miss" terminology (a scheduled job that didn't
  // hit its window) — translate the backend's "stale" wording at the
  // display layer only. Keep the persisted status as job_stale so
  // history filters / metrics / audit logs stay stable.
  if (type === 'job_stale') return 'job miss';
  return type.replace(/_/g, ' ');
}

// App-offline issue titles embed the health-check URL ("Application offline:
// https://…/app/health"), which makes the workbench header unreadable. Split
// the title so the header shows just the label and the endpoint renders on its
// own line below. Display-only — the persisted title (used in emails /
// notifications / lists) is untouched.
function splitIssueTitle(issue: { type: string; title: string }): { heading: string; endpoint: string | null } {
  if (issue.type === 'app_offline') {
    const sep = issue.title.indexOf(': ');
    if (sep !== -1) {
      const endpoint = issue.title.slice(sep + 2).trim();
      return { heading: issue.title.slice(0, sep).trim(), endpoint: endpoint || null };
    }
  }
  return { heading: issue.title, endpoint: null };
}

// Render a user as "Name (username)" to distinguish shared display names.
// Fall back to the username when no display name is available.
function formatAssignee(
  displayName?: string | null,
  username?: string | null,
): string {
  if (!username) return displayName || 'Unassigned';
  return displayName ? `${displayName} (${username})` : username;
}

// Human label for any user reference (actor / recipient / created-by): shows
// "Display Name (username)" so timelines and issue views never surface Ops
// Center's opaque internal row id. Falls back to the numeric id only when
// neither name nor username is known.
function userLabel(
  displayName?: string | null,
  username?: string | null,
  id?: number | null,
): string {
  if (username) return displayName ? `${displayName} (${username})` : username;
  if (displayName) return displayName;
  return id != null ? `User #${id}` : 'Unknown';
}

// MMP pending-approval / pending-review issues are actioned on the MMP
// platform, not via a Ops runbook — the My Actions card offers a deep link +
// a one-click resolve instead of the execution workbench.
function isMmpExternalActionType(type: string) {
  return type === 'mmp_run_pending_approval' || type === 'mmp_pending_review';
}

function mmpExternalActionLabel(type: string) {
  return type === 'mmp_pending_review' ? 'Mark Reviewed' : 'Mark Approved';
}

function issueTypeColor(type: string) {
  switch (type) {
    case 'job_not_triggered': return 'bg-orange-100 text-orange-700';
    case 'job_failed': return 'bg-red-100 text-red-700';
    case 'job_stale': return 'bg-amber-100 text-amber-700';
    case 'app_offline': return 'bg-purple-100 text-purple-700';
    case 'mmp_drift': return 'bg-blue-100 text-blue-700';
    // All four MMP concerns share the blue family so they read as one
    // group in the issues list — the label disambiguates which one.
    case 'mmp_fairness_risk': return 'bg-blue-50 text-blue-700';
    case 'mmp_run_pending_approval': return 'bg-sky-100 text-sky-700';
    case 'mmp_pending_review': return 'bg-cyan-100 text-cyan-700';
    case 'mmp_unapproved_exp_run': return 'bg-indigo-100 text-indigo-700';
    case 'handover_review': return 'bg-yellow-100 text-yellow-700';
    default: return 'bg-slate-100 text-slate-700';
  }
}

function downloadJsonExport(filename: string, payload: unknown) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

