/** Owner-email template engine — the framework-agnostic core (defaults,
 *  serialize/parse, token substitution) now lives in ``./emailTemplate`` so the
 *  onboarding wizard renders identically; only the React/shadcn editor stays
 *  here. */

/** Context that enables the "set as default / replace all" affordance inside
 *  the owner-email template editor. When supplied, the editor can push the
 *  template the user just authored on this action step onto every other
 *  scenario in the same asset or the whole product (persisted server-side via
 *  ``api.applyEmailTemplate``). Omitted in create flows where the asset isn't
 *  persisted yet (nothing to apply onto). */
type EmailTemplateApplyTarget = {
  productId: number;
  assetKind: EmailAssetKind;
  /** Persisted asset row id, or null in a create flow where it isn't saved yet. */
  assetId: number | null;
  /** Friendly asset name shown in the confirm copy, e.g. the job/app name. */
  assetLabel?: string;
  /** Client-side apply: fill the template into EVERY scenario of this asset that
   *  is currently in the edit form's state (across sections), returning how many
   *  were touched. Supplied by the big asset-edit form (ScopeEditor) so the
   *  "this asset" scope rides along with the form's own Save and can never be
   *  clobbered. Omitted by the single-scenario page, which persists via the API
   *  instead. ``mode`` is fill_empty (only blank templates) or overwrite (all). */
  applyToAssetForm?: (template: api.EmailTemplate, mode: 'fill_empty' | 'overwrite') => number;
  /** Called after a successful server-side apply so the caller can refresh
   *  sibling views. Must NOT reset the currently-open edit form (the authored
   *  template is already in form state — a reload would discard unsaved edits). */
  onApplied?: () => void | Promise<void>;
};

/** True when an owner-email template carries no non-blank field — the
 *  client-side mirror of the backend's ``_email_template_is_empty`` so
 *  "set as default" (fill_empty) treats a scenario the same on both sides. */
function isBlankEmailTemplate(template: api.EmailTemplate | null | undefined): boolean {
  if (!template) return true;
  return !(['to', 'cc', 'subject', 'body'] as const).some(
    (key) => String(template[key] ?? '').trim(),
  );
}

/* serializeEmailBody / parseEmailBodyRows / the NBSP padding now live in
 * ./emailTemplate (imported above) so the onboarding wizard shares them. */

function emptyEmailTemplate(assetKind: EmailAssetKind = 'job', scenarioType?: string | null): api.EmailTemplate {
  return { to: '', cc: '', subject: '', body: buildDefaultEmailBody(assetKind, scenarioType) };
}

/** Coerce a persisted (possibly null/partial) email template into the full
 *  editor shape so every field is a defined string. A NULL persisted value
 *  (scenario never had a template) yields the asset-kind default; an
 *  explicitly-saved blank body is preserved (the user may have cleared it
 *  on purpose). */
function normalizeEmailTemplate(
  raw: api.EmailTemplate | null | undefined,
  assetKind: EmailAssetKind = 'job',
  scenarioType?: string | null,
): api.EmailTemplate {
  if (raw == null) return emptyEmailTemplate(assetKind, scenarioType);
  return {
    to: raw.to ?? '',
    cc: raw.cc ?? '',
    subject: raw.subject ?? '',
    body: raw.body ?? '',
  };
}

/** Invisible sentinel appended to an action step's text to mark "this
 *  step performs a send-email-to-owner action". Encoded as a zero-width
 *  space + bracketed token so it round-trips through JSON, never shows
 *  up in copy/paste, and never clashes with anything a human types.
 *
 *  Replaces the previous design where the literal phrase "Send email to
 *  owner" was concatenated into the step text — that made the visible
 *  description ugly when the user already had real instructions in the
 *  step ("Restart service\nSend email to owner"). The flag is now data,
 *  not prose; the UI renders a badge instead. */
const SEND_EMAIL_MARKER = '​[[send_email]]';

/** True when this step carries a send-email action — either via the new
 *  invisible marker, OR (for backward compat with rows saved before this
 *  refactor) by mentioning the legacy "send email" phrase anywhere. */
function isSendEmailStep(text: string): boolean {
  const value = text || '';
  if (value.includes(SEND_EMAIL_MARKER)) return true;
  return /\bsend email\b/i.test(value);
}

/** The user-facing text for a step, with all send-email markers (new
 *  sentinel and legacy "Send email to owner" lines) stripped out. Use
 *  this everywhere a step is rendered to a human — textarea value,
 *  read-only list, "Use A1: …" preset buttons, autofilled notes — so
 *  the marker never leaks into the visible UI or into fields the user
 *  will later edit. */
function stepDisplayText(step: string): string {
  return stripStepMarkers(step).replace(/\s+$/g, '');
}

/** Same as ``stepDisplayText`` but keeps trailing whitespace. Used on the
 *  edit round-trip: the textarea's value is re-encoded on every keystroke,
 *  so trimming here would delete the space the moment the user types it. */
function stripStepMarkers(step: string): string {
  return (step || '')
    .split(/\r?\n/)
    .filter((line) => line.trim().toLowerCase() !== 'send email to owner')
    .join('\n')
    .split(SEND_EMAIL_MARKER)
    .join('');
}

/** Re-encode a step with the send-email flag turned on or off. Always
 *  starts from the stripped form so toggling never accumulates extra
 *  markers or leaves legacy phrases behind. */
function setStepSendEmail(step: string, on: boolean): string {
  const base = stripStepMarkers(step);
  return on ? `${base}${SEND_EMAIL_MARKER}` : base;
}

